using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Object=UnityEngine.Object;
public static class SeatFarProps {
 public static string Run(){var rows=new List<object>();for(int i=1;i<=10;i++){var scene=EditorSceneManager.OpenScene("Assets/Island/MountRuntime/Scenes/MountZone"+i.ToString("00")+".unity");var root=scene.GetRootGameObjects().Single();root.SetActive(true);var zone=root.transform.Cast<Transform>().First(t=>t.name.StartsWith("Zone "));var near=zone.Find("Playable ground - original heights").GetComponentsInChildren<MeshCollider>();var far=zone.Find("Distant context - no physics");var temp=far.gameObject.AddComponent<MeshCollider>();temp.sharedMesh=far.GetComponent<MeshFilter>().sharedMesh;Physics.SyncTransforms();int adjusted=0;float max=0;
 foreach(Transform prop in zone.Find("Nearby authored props")){if(prop.name.StartsWith("architecture / Bridge"))continue;var p=prop.position;var ray=new Ray(p+Vector3.up*500,Vector3.down);bool onNear=near.Any(c=>c.Raycast(ray,out var _,1000));if(onNear)continue;if(temp.Raycast(ray,out var hit,1000)){float change=hit.point.y-p.y;if(Mathf.Abs(change)>.015f){prop.position=new Vector3(p.x,hit.point.y,p.z);max=Mathf.Max(max,Mathf.Abs(change));adjusted++;}}}
 Object.DestroyImmediate(temp);foreach(var oc in root.GetComponentsInChildren<IslandGame.BattleOccluder>(true))Object.DestroyImmediate(oc);root.SetActive(false);EditorSceneManager.SaveScene(scene);rows.Add(new{zone=i,adjusted,maxAdjustment=max});}
 EditorSceneManager.OpenScene("Assets/Island/Scenes/Island.unity");string result=JsonConvert.SerializeObject(rows,Formatting.Indented);File.WriteAllText("C:/Users/SHK/mount-sunday-playtest-20261108/evidence/far-prop-grounding.json",result);return result;}
}
